<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLAttributes } from 'svelte/elements'; import { getDrawerContext } from './drawer-context.svelte.js'; interface Props extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> { children?: Snippet; threshold?: number; ref?: HTMLDivElement | null; } let { children, threshold = 40, ref = $bindable(null), onpointerdown, ...rest }: Props = $props(); const drawer = getDrawerContext(); function start(event: PointerEvent) { onpointerdown?.(event as PointerEvent & { currentTarget: EventTarget & HTMLDivElement }); if (event.defaultPrevented || drawer.open || !(event.currentTarget instanceof HTMLElement)) return; const startX = event.clientX; const startY = event.clientY; const node = event.currentTarget; const end = (e: PointerEvent) => { const distance = drawer.swipeDirection === 'down' ? startY - e.clientY : drawer.swipeDirection === 'up' ? e.clientY - startY : drawer.swipeDirection === 'right' ? startX - e.clientX : e.clientX - startX; if (distance > threshold) drawer.setOpen(true, e, 'swipe'); node.removeEventListener('pointerup', end); }; node.addEventListener('pointerup', end); } </script><div bind:this={ref} {...rest} aria-hidden="true" data-swipe-direction={drawer.swipeDirection} onpointerdown={start}>{@render children?.()}</div>
